 const translateNodes=function(root=document.body){
  if(ccLang!=='en'||!root)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];
  while(walker.nextNode())nodes.push(walker.currentNode);
  for(const node of nodes){const el=node.parentElement;if(!el||el.closest('script,style,pre,code,textarea,input,[contenteditable],.editor-shell,.inline-code,.g-code,.adv-code,.run-output,'+protectedUserText))continue;
   if(el.tagName==='OPTION'&&!el.hasAttribute('value'))el.setAttribute('value',el.textContent);
   const en=ccEnglish(node.nodeValue);if(en!==node.nodeValue)node.nodeValue=en;
  }
  for(const el of root.querySelectorAll('[title],[aria-label],[placeholder]')){if(el.closest('.editor-shell,.inline-code,.g-code,.adv-code,'+protectedUserText))continue;for(const attr of ['title','aria-label','placeholder']){const v=el.getAttribute(attr);if(v){const en=ccEnglish(v);if(en!==v)el.setAttribute(attr,en)}}}
 };
